CREATE OR REPLACE EDITIONABLE PROCEDURE "%USER_NAME%"."SIGNATURE_REQUEST_COMPLETE" (pHASH VARCHAR2)
AS
    email LTS_EMAIL := LTS_EMAIL();
    vName VARCHAR2(255);
    vDate DATE;
BEGIN
    SELECT last_name||', '||first_name, sr_date
    INTO vName, vDate
    FROM session_review
        INNER JOIN clients ON session_review.case_number = clients.case_number
    WHERE signature_request_hash = pHASH;         

    email.subject := 'Signature Request Completed: '||vName||' '||TO_CHAR(vDate, 'MM/YYYY');
    email.add_to_address('kristine.schwab@life-ts.com');
    email.send_email();
EXCEPTION
    WHEN OTHERS THEN
        BEGIN
            email := LTS_EMAIL();
            email.subject := 'Signature Request Completed: Notification Error ';
            email.add_to_address('michael.e.chambers@gmail.com');
            email.send_email();
        EXCEPTION
            WHEN OTHERS THEN
                NULL;
        END;
END SIGNATURE_REQUEST_COMPLETE;
/
